steps = [
    step("接收窗口随缓冲区被填满而变小:接收方(客户端)在 connect 之前把 SO_RCVBUF 设成 64 KiB 且不调用 recv,服务端持续发送。接收方通告的窗口缩放系数是 3(窗口字段 × 2^3);SO_RCVBUF 读回的却是 342972 字节——设成 64 KiB 并没有生效(见第三节)。接收方的 ACK 通告的窗口:第 1 个 ACK 字段 42872,实际窗口 342976 字节;随着已收到的字节增加,确认号 16332 时 326648、32664 时 310320、48996 时 293992、65328 时 277664……到确认号 294808 时只剩 48224,311140 时 31896,327472 时 15568,最后一个 ACK(确认号 327680)通告窗口 15360 字节。窗口始终没有恰好降到 0,最小 15360 字节,小于一个 MSS(16344),发送方因此不再发小包。FIONREAD 显示接收缓冲区里可读 327680 字节;服务端的 send() 一共让内核收下了 474460 字节 ≈ 接收缓冲区的 327680 + 发送方自己的发送缓冲区(SO_SNDBUF 146988),再往后 send() 就返回 EAGAIN。这就是流量控制:接收方告诉发送方“我还能收多少”,发送方不会超过它。", t=tl(S(1)), mark=lidx(S(1), '         7           294808', '         9           327472', '        10           327680'), done=lidx(S(1), '接收方(客户端,connect', '         1                0', '共 23 种', '接收方什么都没读时'), b=bars([['初始窗口', 342976, '342,976'], ['确认号 65328 时', 277664, '277,664'], ['确认号 294808 时', 48224, '48,224'], ['最后一个 ACK', 15360, '15,360']], 342976, mark=[3], done=[0, 1, 2]), kv=KV([['窗口缩放', '2^3'], ['初始窗口', '342,976 字节'], ['最小窗口', '15,360 字节(< 1 个 MSS,发送方停发)'], ['send() 收下', '474,460 = 接收缓冲区 327,680 + 发送缓冲区 146,988']], ['最小窗口'])),
    step("接收方读得慢,发送方就被拖慢:接收方每次读 64 KiB 后睡眠来控制读速。读速约 1 MB/s 时,发送方在 2 秒里 send() 出去 4.8 MB(含进入缓冲区的),接收方读走 1.9 MB,折合 0.9 MB/s;读速约 20 MB/s 时,发送方 send() 出去 35.8 MB,接收方读走 33.0 MB,折合 16.5 MB/s;不限速时发送 5926.1 MB,读走 5926.1 MB,折合 1974.4 MB/s。发送速率被接收方的读速限制住,多出来的只是缓冲区能装下的那一点;接收窗口就是对端告诉你“我还能收多少”。", t=tl(S(2)), mark=lidx(S(2), '读速约 1 MB/s', '读速约 20 MB/s'), done=lidx(S(2), '读速不限速', '发送速率被接收方的读速'), b=bars([['读速 ~1 MB/s · 接收方读走', 1.9, '1.9 MB'], ['读速 ~20 MB/s · 接收方读走', 33.0, '33.0 MB'], ['不限速 · 接收方读走', 5926.1, '5926.1 MB']], 5926.1, mark=[0], done=[1, 2]), kv=KV([['读速 ~1 MB/s', '2 秒读走 1.9 MB'], ['读速 ~20 MB/s', '2 秒读走 33.0 MB'], ['不限速', '2 秒读走 5926.1 MB']], ['读速 ~1 MB/s'])),
    step("窗口大小与吞吐:往返 100 ms(netlab 每个方向 50 ms)的回环上,接收方 connect 之前设 SO_RCVBUF,发送方持续发 3 秒。设成 16384、65536、262144 的接收方,读回的实际缓冲区分别是 326640、342972、277644 字节——macOS 在这个范围里没有照我设的值走(小于约 256 KiB 的设置不起作用,读回都是 28~34 万字节),吞吐也几乎一样:3.02、3.04、3.05 MB/s,与“读回的窗口 ÷ RTT”的 3.27、3.43、2.78 MB/s 同量级;设成 1048576 后读回 1061580 字节,吞吐 10.79 MB/s,与理论上限 10.62 MB/s 几乎一致。也就是说每个往返最多发一个窗口的数据,吞吐 ≈ 窗口 ÷ RTT——窗口越小,在往返时间长的链路上越吃亏(下面 BDP 一篇展开)。", t=tl(S(3)), mark=lidx(S(3), '接收方 SO_RCVBUF =  1048576', '接收方 SO_RCVBUF =    16384'), done=lidx(S(3), '接收方 SO_RCVBUF =    65536', '接收方 SO_RCVBUF =   262144', '窗口越小'), b=bars([['设 16 KiB · 实测', 3.02, '3.02 MB/s'], ['设 64 KiB · 实测', 3.04, '3.04 MB/s'], ['设 256 KiB · 实测', 3.05, '3.05 MB/s'], ['设 1 MiB · 实测', 10.79, '10.79 MB/s'], ['设 1 MiB · 窗口 ÷ RTT', 10.62, '10.62 MB/s']], 10.79, mark=[3, 4], done=[0, 1, 2]), kv=KV([['设 16 / 64 / 256 KiB', '读回都在 28~34 万字节,吞吐都约 3 MB/s'], ['设 1 MiB', '读回 1,061,580,吞吐 10.79 MB/s'], ['吞吐', '≈ 窗口 ÷ RTT']], ['吞吐'])),
    step("窗口更新:接收缓冲区被塞到只剩 7688 字节的窗口后,应用每次只读 100 字节,共读 400 次(40000 字节),这段时间里只抓到 1 个“窗口更新”ACK(确认号不变、只有窗口变大),它把窗口一次从 7688 字节通告成 269000 字节,增加了 261312 字节——比我读走的 40000 字节多得多,为什么会这样没有查清(可能和内核自动调整接收缓冲区有关)。不管怎样,接收方没有读走 100 字节就立刻通告一次小窗口:等空出的空间累积到一定程度才发窗口更新,避免发送方反复发很小的包(糊涂窗口综合征,RFC 1122)。", t=tl(S(4)), mark=lidx(S(4), '窗口更新的前几次', '每次窗口变大的幅度'), done=lidx(S(4), '接收方读了 400 次'), b=bars([['更新前的窗口', 7688, '7,688'], ['更新后的窗口', 269000, '269,000'], ['我读走的字节', 40000, '40,000']], 269000, mark=[1], done=[0, 2]), kv=KV([['读 400 次 × 100 字节', '只触发 1 次窗口更新'], ['窗口', '7,688 → 269,000'], ['避免', '糊涂窗口综合征']], ['避免'])),
]
